#include <stdint.h>
#include <stdio.h> // For printf

// Stack symbols
uint64_t _stack[512];
uint64_t * const _stack_top = _stack + 512;

// tohost symbol for simulation termination
extern volatile uint64_t tohost;

// Globals for experiment
#define NUM_TRIALS 25 // Number of measurement iterations per scenario
#define NUM_ATTACKER_STORES 8 // Number of unresolved stores issued by the attacker
#define NOP_COUNT 16 // Number of NOPs for pipeline settling

// Static buffers for memory access, aligned to avoid unexpected cache behavior
// Adhering to memory footprint constraints: max 8KB for single array, total static data under 16KB.
// attacker_stores_array: NUM_ATTACKER_STORES * sizeof(uint64_t) = 8 * 8 = 64 bytes.
// attacker_load_target: sizeof(uint64_t) = 8 bytes.
// non_aliasing_victim_target: sizeof(uint64_t) = 8 bytes.
// results_alias/no_alias: 2 * NUM_TRIALS * sizeof(uint64_t) = 2 * 25 * 8 = 400 bytes.
// Total static data is ~480 bytes, well within 16KB limit.
static volatile uint64_t attacker_stores_array[NUM_ATTACKER_STORES] __attribute__((aligned(64)));
static volatile uint64_t attacker_load_target __attribute__((aligned(64)));
static volatile uint64_t non_aliasing_victim_target __attribute__((aligned(64)));

// Store results for each scenario
uint64_t results_alias[NUM_TRIALS];
uint64_t results_no_alias[NUM_TRIALS];

// Trap handler for bare-metal RISC-V, set up as minimal as possible.
// In this isolated simulation, it primarily serves to halt on unexpected events.
__attribute__((naked))
void trap_handler() {
    // Save sp, load trap handler sp if mscratch holds it (not strictly needed for this simple halt)
    asm volatile(
        "csrrw sp, mscratch, sp
" 
        "j trap_exit_point
"
    );

    asm volatile(
    "trap_exit_point:
"
        "extern volatile uint64_t tohost;
"
        "la t0, tohost
"
        "li t1, 1
"
        "sd t1, 0(t0)
" // Set tohost to 1 to end simulation
        "1: j 1b
"      // Infinite loop to halt
    );
}

// Helper function to print experiment results to stdout.
void print_results(const char* label, uint64_t* results, int count) {
    printf("%s: [", label);
    for (int i = 0; i < count; i++) {
        printf("%lu", results[i]); // Using %lu for uint64_t on RV64
        if (i < count - 1) {
            printf(", ");
        }
    }
    printf("]
");
}

// Main experiment logic
int main() {
    // Set up M-mode trap vector (mtvec) to point to our trap handler.
    // This ensures graceful simulation termination on any unexpected exception.
    asm volatile("csrw mtvec, %0" :: "r"(&trap_handler));

    // Initialize addresses. Using distinct static addresses to represent different memory locations.
    // Offsets are chosen to ensure distinct cache lines/pages for different variables
    // within the small static memory footprint allowed.
    attacker_load_target = 0; // Placeholder, will be set in each trial.
    non_aliasing_victim_target = 0x1000; // Example distinct address.

    // Initialize attacker_stores_array with distinct dummy values (addresses).
    // The values stored don't matter, only the store operations themselves.
    for (int i = 0; i < NUM_ATTACKER_STORES; i++) {
        attacker_stores_array[i] = (uint64_t)(0x2000 + i * 8); // Ensure distinct addresses for each store.
    }

    printf("Starting memory dependence predictor attack experiment.
");
    printf("Parameters: NUM_TRIALS=%lu, NUM_ATTACKER_STORES=%lu, NOP_COUNT=%lu
",
           (uint64_t)NUM_TRIALS, (uint64_t)NUM_ATTACKER_STORES, (uint64_t)NOP_COUNT);

    // --- Scenario 1: Attacker's load aliases with Victim's store (expected SLOW timing) ---
    // This serves as the 'positive control' for the timing difference.
    printf("Running ALIASING scenario (Positive Control - Expected SLOW)...
");
    for (int i = 0; i < NUM_TRIALS; i++) {
        uint64_t start_time = 0;
        uint64_t end_time = 0;
        volatile uint64_t speculative_read_val = 0; // Prevents compiler from optimizing out the load.

        // Make attacker_load_target address unique for each trial and distinct from other arrays.
        // This helps reduce noise from prior trial's cache/predictor state.
        attacker_load_target = 0x3000 + (uint64_t)i * 8; 

        // Start timing measurement. NOPs are for pipeline settling before rdcycle.
        asm volatile (
            ".rept %0
	"
            "nop
	"
            ".endr
	"
            "rdcycle %1
	"
            : : "i"(NOP_COUNT), "r"(start_time)
        );

        // Attacker: Issue unresolved stores.
        // These stores are intended to fill the LSU and remain in-flight.
        for (int j = 0; j < NUM_ATTACKER_STORES; j++) {
            asm volatile("sd x0, 0(%0)" :: "r"(&attacker_stores_array[j]));
        }

        // Attacker: Speculative Load.
        // The memory dependence predictor is expected to predict no alias with preceding stores,
        // allowing this load to speculatively bypass them.
        asm volatile("ld %0, 0(%1)" : "=r"(speculative_read_val) : "r"(&attacker_load_target));

        // Victim: Store to the *same* address as the attacker's speculative load.
        // This action, happening after the speculative load but before it commits,
        // reveals the true dependency and triggers a memory ordering violation.
        // The violation causes a pipeline machine clear.
        asm volatile("sd x0, 0(%0)" :: "r"(&attacker_load_target));

        // NOPs to ensure the penalty of the machine clear is absorbed before ending timing.
        asm volatile (
            ".rept %0
	"
            "nop
	"
            ".endr
	"
            "rdcycle %1
	"
            : : "i"(NOP_COUNT), "r"(end_time)
        );

        results_alias[i] = end_time - start_time;
    }

    // --- Scenario 2: Attacker's load does NOT alias with Victim's store (expected FAST timing) ---
    // This serves as the 'negative control' or baseline comparison.
    printf("Running NO ALIASING scenario (Negative Control - Expected FAST)...
");
    for (int i = 0; i < NUM_TRIALS; i++) {
        uint64_t start_time = 0;
        uint64_t end_time = 0;
        volatile uint64_t speculative_read_val = 0;

        // Ensure attacker_load_target and non_aliasing_victim_target are distinct and unique per trial.
        attacker_load_target = 0x4000 + (uint64_t)i * 8; 
        non_aliasing_victim_target = 0x5000 + (uint64_t)i * 8; 

        // Start timing measurement.
        asm volatile (
            ".rept %0
	"
            "nop
	"
            ".endr
	"
            "rdcycle %1
	"
            : : "i"(NOP_COUNT), "r"(start_time)
        );

        // Attacker: Issue unresolved stores.
        for (int j = 0; j < NUM_ATTACKER_STORES; j++) {
            asm volatile("sd x0, 0(%0)" :: "r"(&attacker_stores_array[j]));
        }

        // Attacker: Speculative Load.
        asm volatile("ld %0, 0(%1)" : "=r"(speculative_read_val) : "r"(&attacker_load_target));

        // Victim: Store to a *different* address.
        // No memory ordering violation is expected here, thus no machine clear.
        asm volatile("sd x0, 0(%0)" :: "r"(&non_aliasing_victim_target));

        // NOPs for pipeline settling.
        asm volatile (
            ".rept %0
	"
            "nop
	"
            ".endr
	"
            "rdcycle %1
	"
            : : "i"(NOP_COUNT), "r"(end_time)
        );

        results_no_alias[i] = end_time - start_time;
    }

    // Print raw results for auditing and analysis.
    print_results("ALIasing_Cycles", results_alias, NUM_TRIALS);
    print_results("NO_ALIasing_Cycles", results_no_alias, NUM_TRIALS);

    // Experiment completion signal.
    printf("Experiment complete.
");
    tohost = 1; // Signal fesvr to end simulation
    while (1) {} // Infinite loop to halt the core
}

// Minimal _start function for bare-metal RISC-V.
// Sets up the stack pointer and transfers control to main.
void _start() {
    // Set stack pointer to the top of our static stack.
    asm volatile("mv sp, %0" :: "r"(_stack_top));

    // Call the main function to start the experiment.
    main();

    // In case main returns (which it should not for this program), halt the simulation.
    extern volatile uint64_t tohost;
    tohost = 1;
    while (1) {}
}

